package lk.medichannel.user;
import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lk.medichannel.audit.*; import lk.medichannel.auth.*; import lk.medichannel.crypto.CryptoService; import lk.medichannel.security.CurrentUser; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminUserController {
 private final UserRepository users; private final CryptoService crypto; private final PasswordEncoder passwords; private final AuditService audit; private final AuthService auth;
 public AdminUserController(UserRepository users,CryptoService crypto,PasswordEncoder passwords,AuditService audit,AuthService auth,AuditLogRepository auditLogs){this.users=users;this.crypto=crypto;this.passwords=passwords;this.audit=audit;this.auth=auth;this.auditLogs=auditLogs;}
 public record CreateStaffRequest(@NotBlank @Email String email,@NotBlank @Size(min=12,max=72) String temporaryPassword,@NotNull UserRole role){} public record ResetPasswordRequest(@NotBlank @Size(min=12,max=72) String temporaryPassword){}
 @PostMapping("/users") @Transactional @ResponseStatus(HttpStatus.CREATED) public AuthDtos.UserResponse create(@AuthenticationPrincipal CurrentUser actor,@Valid @RequestBody CreateStaffRequest r,HttpServletRequest http){if(r.role()==UserRole.CUSTOMER||r.role()==UserRole.ADMIN)throw new IllegalArgumentException("Only DOCTOR or MANAGER staff accounts can be created here");String hash=crypto.hmac(r.email());if(users.findByEmailLookupHash(hash).isPresent())throw new IllegalArgumentException("An account already exists for that email");User u=new User();u.setEmailCiphertext(crypto.encrypt(r.email().trim().toLowerCase()));u.setEmailLookupHash(hash);u.setPasswordHash(passwords.encode(r.temporaryPassword()));u.setRole(r.role());u.setPasswordChangeRequired(true);users.save(u);audit.log(actor.id(),"STAFF_ACCOUNT_CREATED","USER",u.getId(),http);return auth.toResponse(u);}
 @GetMapping("/users") public Page<AuthDtos.UserResponse> list(@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="25") @Min(1) @Max(100) int size,@RequestParam(required=false) UserRole role){Pageable p=PageRequest.of(page,size,Sort.by("createdAt").descending());return (role==null?users.findAll(p):users.findAllByRole(role,p)).map(auth::toResponse);}
 @PatchMapping("/users/{id}/active") @Transactional public AuthDtos.UserResponse active(@AuthenticationPrincipal CurrentUser actor,@PathVariable Long id,@RequestParam boolean value,HttpServletRequest http){if(actor.id().equals(id)&&!value)throw new IllegalArgumentException("You cannot deactivate your own account");User u=users.findById(id).orElseThrow(()->new IllegalArgumentException("Account not found"));u.setActive(value);audit.log(actor.id(),value?"ACCOUNT_ACTIVATED":"ACCOUNT_DEACTIVATED","USER",id,http);return auth.toResponse(u);}
 @PostMapping("/users/{id}/reset-password") @Transactional @ResponseStatus(HttpStatus.NO_CONTENT) public void reset(@AuthenticationPrincipal CurrentUser actor,@PathVariable Long id,@Valid @RequestBody ResetPasswordRequest r,HttpServletRequest http){User u=users.findById(id).orElseThrow(()->new IllegalArgumentException("Account not found"));u.setPasswordHash(passwords.encode(r.temporaryPassword()));u.setPasswordChangeRequired(true);u.setFailedLoginAttempts(0);u.setLockedUntil(null);audit.log(actor.id(),"PASSWORD_RESET","USER",id,http);}
 @GetMapping("/audit-logs") public Page<AuditLog> audit(@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="50") @Min(1) @Max(100) int size){return auditLogs.findAll(PageRequest.of(page,size,Sort.by("createdAt").descending()));} private final AuditLogRepository auditLogs;
}
